from itertools import product

def placements(grid):
    R=len(grid); C=len(grid[0]); cells={(r,c) for r in range(R) for c in range(C) if grid[r][c]==8}
    pats={1:((0,0),(0,1),(1,0),(1,1)),2:((0,1),(1,0),(1,1)),3:((0,0),(0,1),(1,1)),4:((0,0),(1,0),(1,1))}
    opts=[]
    for col,shape in pats.items():
        for r in range(R-1):
            for c in range(C-1):
                coords=frozenset((r+dr,c+dc) for dr,dc in shape)
                if coords <= cells: opts.append((col,coords))
    return cells,opts

def covers(grid,limit=1000):
    cells,opts=placements(grid); out=[]
    def rec(rem, chosen):
        if not rem:
            out.append(chosen.copy()); return
        if len(out)>=limit:return
        cell=min(rem)
        for col,s in opts:
            if cell in s and s<=rem:
                rec(rem-s,chosen+[(col,s)])
    rec(cells,[])
    return out

