    placements = []
    for color, shape in shapes.items():
        for r in range(rows - 1):
            for c in range(cols - 1):
                part = frozenset((r + dr, c + dc) for dr, dc in shape)
                if part <= cells:
                    placements.append((color, part))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for color, part in placements:
            if cell in part and part <= remaining:
                rest = cover(remaining - part)
                if rest is not None:
                    return [(color, part)] + rest
        return None

    result = [[0] * cols for _ in range(rows)]
    for color, part in cover(cells):
        for r, c in part:
            result[r][c] = color
    return result
